def _set_user_category(inv: Invocation, username: str, category: Any) -> bool:
    """UpdateUser's category: Portal 管理员, 一般用户 or 实习用户, changed only by a Portal 管理员
    in either permission mode; the Portal always keeps one active Portal 管理员."""
    from management_portal import permission_system
    from management_portal.permission_system.categories import category_name

    try:
        category = category_name(category)
    except ValueError as exc:
        raise invalid(str(exc)) from exc
    user = _access().user(username)
    if not user.get("configured") or user.get("status") == "deleted":
        raise not_found(f"用户不存在：{username}")
    if category == permission_system.user_category(username):
        return False
    if permission_system.user_category(inv.caller) != "portal_admin":
        raise InstructionError("instruction.forbidden", "只有 Portal 管理员可以修改 User 分类")
    if category != "portal_admin" and permission_system.user_category(username) == "portal_admin":
        others = [name for name, value in permission_system.user_categories().items()
                  if value == "portal_admin" and name != username and _access().is_active(name)]
        if not others:
            raise invalid("至少保留一位启用中的 Portal 管理员")
    changed = permission_system.set_user_category(username, category, actor=inv.caller)
    if changed:
        _access().audit(inv.caller, "user_category_updated", target=username, details={"category": category})
    return changed

