def coverage(self, a_path: Sequence[str], now: float) -> Coverage:
    """The R nodes under which the action at ``a_path`` is permitted, minus its holes."""

class Decision:
    """The answer for one ``(p, a, r)``: the permit entry that covers it, or why not."""

    allowed: bool
    permit: Entry | None = None
    deny: Entry | None = None

    @property
    def reason(self) -> str:
        if self.allowed:
            return "permitted"
        return "denied" if self.deny is not None else "no_permit"

def _decide(self, principal: str, items: list[tuple[str, str]]):
    """Decisions under the active scheme, following a change of scheme once."""
    scheme, engine, _instance = self._load()
    try:
        return scheme, engine.decide(principal, items)
    except InstanceChanged as changed:
        scheme, engine, _instance = self._load(changed.token)
        return scheme, engine.decide(principal, items)

